CREATE TABLE `cash_registers` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`unit_id` BIGINT UNSIGNED NULL,`status` ENUM('OPEN', 'CLOSED') NOT NULL DEFAULT 'OPEN',`opening_balance_cents` BIGINT UNSIGNED NOT NULL,`closing_balance_cents` BIGINT UNSIGNED NULL,`opened_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`closed_at` DATETIME(3) NULL,`opened_by_user_id` BIGINT UNSIGNED NULL,`opened_by_session_id` BIGINT UNSIGNED NULL,`closed_by_user_id` BIGINT UNSIGNED NULL,`closed_by_session_id` BIGINT UNSIGNED NULL,`notes` VARCHAR(500) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `cash_registers_public_id_key` (`public_id`),INDEX `cash_registers_tenant_id_unit_id_status_idx` (`tenant_id`,`unit_id`,`status`),CONSTRAINT `cash_registers_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `cash_registers_unit_id_fkey` FOREIGN KEY (`unit_id`) REFERENCES `business_units`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `cash_registers_opened_by_user_id_fkey` FOREIGN KEY (`opened_by_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `cash_registers_opened_by_session_id_fkey` FOREIGN KEY (`opened_by_session_id`) REFERENCES `user_sessions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `cash_registers_closed_by_user_id_fkey` FOREIGN KEY (`closed_by_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `cash_registers_closed_by_session_id_fkey` FOREIGN KEY (`closed_by_session_id`) REFERENCES `user_sessions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `cash_movements` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`cash_register_id` BIGINT UNSIGNED NOT NULL,`type` ENUM('MANUAL', 'PAYMENT') NOT NULL,`direction` ENUM('IN', 'OUT') NOT NULL,`amount_cents` BIGINT UNSIGNED NOT NULL,`reason` VARCHAR(500) NULL,`payment_id` BIGINT UNSIGNED NULL,`user_id` BIGINT UNSIGNED NULL,`session_id` BIGINT UNSIGNED NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `cash_movements_public_id_key` (`public_id`),UNIQUE INDEX `cash_movements_payment_id_key` (`payment_id`),INDEX `cash_movements_tenant_id_cash_register_id_created_at_idx` (`tenant_id`,`cash_register_id`,`created_at`),CONSTRAINT `cash_movements_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `cash_movements_cash_register_id_fkey` FOREIGN KEY (`cash_register_id`) REFERENCES `cash_registers`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `cash_movements_payment_id_fkey` FOREIGN KEY (`payment_id`) REFERENCES `payments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `cash_movements_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `cash_movements_session_id_fkey` FOREIGN KEY (`session_id`) REFERENCES `user_sessions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `receipts` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`payment_id` BIGINT UNSIGNED NOT NULL,`number` VARCHAR(32) NOT NULL,`issued_by_user_id` BIGINT UNSIGNED NULL,`issued_by_session_id` BIGINT UNSIGNED NULL,`issued_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `receipts_public_id_key` (`public_id`),UNIQUE INDEX `receipts_payment_id_key` (`payment_id`),UNIQUE INDEX `receipts_tenant_id_number_key` (`tenant_id`,`number`),CONSTRAINT `receipts_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `receipts_payment_id_fkey` FOREIGN KEY (`payment_id`) REFERENCES `payments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `receipts_issued_by_user_id_fkey` FOREIGN KEY (`issued_by_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `receipts_issued_by_session_id_fkey` FOREIGN KEY (`issued_by_session_id`) REFERENCES `user_sessions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
